import{_ as s,a0 as l,w as a,s as p,ao as u,I as i,x as r,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"OWL 项目：物联网正尝试在灾难中让一切保持联络 | LCTT x X-CMD","titleTemplate":false,"description":"OWL 项目：物联网正尝试在灾难中让一切保持联络 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OWL 项目：物联网正尝试在灾难中让一切保持联络 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OWL 项目：物联网正尝试在灾难中让一切保持联络 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200706 Project OWL- IoT trying to hold connectivity together in disasters","title":"OWL 项目：物联网正尝试在灾难中让一切保持联络","tag":"202007","desc":""},"relativePath":"202007/20200706 Project OWL- IoT trying to hold connectivity together in disasters.md","filePath":"[post].md"}'),d={name:"202007/20200706 Project OWL- IoT trying to hold connectivity together in disasters.md"};function m(y,t,f,w,L,T){const o=l("Link");return a(),p("div",null,[t[15]||(t[15]=u('<h1 id="owl-项目-物联网正尝试在灾难中让一切保持联络" tabindex="-1">OWL 项目：物联网正尝试在灾难中让一切保持联络 <a class="header-anchor" href="#owl-项目-物联网正尝试在灾难中让一切保持联络" aria-label="Permalink to “OWL 项目：物联网正尝试在灾难中让一切保持联络”">​</a></h1><blockquote><p>当自然灾害破坏了传统的通信连接时，配置在<ruby>多跳网络<rt>mesh network</rt></ruby>的物联网设备可以迅速部署以提供基本的连接。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202007/21/135614mwr8rxr6lw5xefjs.jpg" alt=""></p><p>OWL 项目负责人在最近的开源峰会上说，一个以多跳网络、物联网和 LoRa 连接为中心的开源项目可以帮助急救和受灾人员在自然灾害之后保持联系。</p><p>OWL 项目的应用场景是当在自然灾害之后频繁发生的通信中断时。无论是蜂窝网络还是有线网络，大范围的中断会频繁阻碍急救服务、供应和在暴风雨或其他重大灾难后必须解决关键问题的信息流。</p><p>该项目通过一大群“<ruby>鸭子<rt>duck</rt></ruby>”（便宜、易于部署且不需要现有基础设施支持的小型无线模块）实现这个目的。一些“鸭子”是太阳能的，其它一些则用的是耐用电池。每只“鸭子”配备一个 LoRa 无线电，用于在网络上和其它“鸭子”进行通信，同时还配备有 Wi-Fi，而且可能配备蓝牙和 GPS 来实现其他功能。</p><p>这个想法是这样的，当网络瘫痪时，用户可以使用他们的智能手机或者笔记本电脑与“鸭子”建立一个 Wi-Fi 连接，这个“鸭子”可以将小块的信息传递到网络的其他部分。信息向网络后端传递，直到到达“<ruby>鸭子爸爸<rt>papaduck</rt></ruby>”，“鸭子爸爸”装备了可以与云上的 OWL 数据管理系统连接的卫星系统（OWL 代表 ”<ruby>组织<rt>organization</rt></ruby>、<ruby>位置<rt>whereabouts</rt></ruby>和<ruby>物流<rt>logistics</rt></ruby>”）。信息可以通过云在智能手机或者网页上进行可视化，甚至可以通过 API 插入到现有的系统中。</p><p>秘密在于“<ruby>鸭群<rt>ClusterDuck</rt></ruby>” 协议，这是一个开源固件，即使在一些模块不能正常工作的网络中，它仍然能保持信息流通。它就是设计用来工作在大量便宜且容易获取的计算硬件上，类似树莓派的硬件，这样可以更容易且更快捷的建立一个“鸭群”网络。</p><p>创始人 Bryan Knouse 表示，这个项目的创建，是因为在 2017 年和 2018 年的毁灭性飓风中，要与受影响社区进行有效的通信而采取救援措施，面临着巨大的困难。</p><p>“我们的一些创始成员经历了这些灾难，然后我们会问‘我们该做些什么？’”，他说道。</p><p>在马亚圭斯，该项目有一批来自波多黎各大学的学生和教授，大多数的系统测试都在那里进行。Knouse 说，校园中目前有 17 个太阳能“鸭子”，分布在屋顶和树上，并且计划增加数量。</p><p>他说，“这种关系实际上创建了一个开源社区，这些学生和教授正在帮助我们开发这个项目。”</p><hr>',13)),i("p",null,[t[1]||(t[1]=r("via: ",-1)),e(o,{href:"https://www.networkworld.com/article/3564980/project-owl-iot-trying-to-hold-connectivity-together-in-disasters.html"},{default:n(()=>[...t[0]||(t[0]=[r("https://www.networkworld.com/article/3564980/project-owl-iot-trying-to-hold-connectivity-together-in-disasters.html",-1)])]),_:1})]),i("p",null,[t[6]||(t[6]=r("作者：",-1)),e(o,{href:"https://www.networkworld.com/author/Jon-Gold/"},{default:n(()=>[...t[2]||(t[2]=[r("Jon Gold",-1)])]),_:1}),t[7]||(t[7]=r(" 选题：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[3]||(t[3]=[r("lujun9972",-1)])]),_:1}),t[8]||(t[8]=r(" 译者：",-1)),e(o,{href:"https://github.com/Yufei-Yan"},{default:n(()=>[...t[4]||(t[4]=[r("Yufei-Yan",-1)])]),_:1}),t[9]||(t[9]=r(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[r("wxy",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=r("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[r("LCTT",-1)])]),_:1}),t[13]||(t[13]=r(" 原创编译，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[r("Linux中国",-1)])]),_:1}),t[14]||(t[14]=r(" 荣誉推出",-1))])])}const x=s(d,[["render",m]]);export{h as __pageData,x as default};
